function fewestTransfers(payments: number[][]): number {
  const net = new Map<number, number>();
  for (const [a, b, x] of payments) {
    net.set(a, (net.get(a) ?? 0) + x);
    net.set(b, (net.get(b) ?? 0) - x);
  }
  const bal = [...net.values()].filter(v => v !== 0);
  const dfs = (i: number): number => {
    while (i < bal.length && bal[i] === 0) i++;
    if (i === bal.length) return 0;
    let best = Infinity;
    const tried = new Set<number>();
    for (let j = i + 1; j < bal.length; j++) {
      if (bal[i] * bal[j] >= 0 || tried.has(bal[j])) continue;
      tried.add(bal[j]);
      bal[j] += bal[i];
      best = Math.min(best, 1 + dfs(i + 1));
      bal[j] -= bal[i];
    }
    return best;
  };
  return dfs(0);
}

