class Solution:
    def fewestTransfers(self, payments: List[List[int]]) -> int:
        net = defaultdict(int)
        for a, b, x in payments:
            net[a] += x
            net[b] -= x
        bal = [v for v in net.values() if v != 0]

        def dfs(i):
            while i < len(bal) and bal[i] == 0:
                i += 1
            if i == len(bal):
                return 0
            best, tried = float("inf"), set()
            for j in range(i + 1, len(bal)):
                if bal[i] * bal[j] >= 0 or bal[j] in tried:
                    continue
                tried.add(bal[j])
                bal[j] += bal[i]
                best = min(best, 1 + dfs(i + 1))
                bal[j] -= bal[i]
            return best

        return dfs(0)

