function fewestTransfers(payments: number[][]): number {
  const net = new Map<number, number>();
  for (const [a, b, x] of payments) {
    net.set(a, (net.get(a) ?? 0) + x);
    net.set(b, (net.get(b) ?? 0) - x);
  }
  const bal = [...net.values()].filter(v => v !== 0);
  const k = bal.length, full = 1 << k;
  const sum = new Array(full).fill(0), groups = new Array(full).fill(0);
  for (let mask = 1; mask < full; mask++) {
    const low = mask & -mask, i = 31 - Math.clz32(low);
    sum[mask] = sum[mask ^ low] + bal[i];
    let best = 0;
    for (let j = 0; j < k; j++) if (mask & (1 << j)) best = Math.max(best, groups[mask ^ (1 << j)]);
    groups[mask] = best + (sum[mask] === 0 ? 1 : 0);
  }
  return k - groups[full - 1];
}

